  function vals(c) { const p = IB.pOf(c) || {}; return { patient_name: PT.name(p), patient_dob: p.dob ? longD(new Date(p.dob)) : '', patient_address: [p.addr, p.city, p.postcode].filter(Boolean).join(', ') || 'address on file', clinic_name: 'LeafEase Medical Centre', practice_name: 'LeafEase Clinic', clinic_phone: '+44 116 496 0100', pharmacy_name: 'your local pharmacy', appointment_date: longD(new Date(c.submitted)), appointment_time: '', service_name: c.lt.cat }; }
