      const edit = !c.closed && !adm() && (lt.stage === 'draft' || (lt.stage === 'signature' && isSigner(c)));
      const tools = edit ? `<div class="hl-tools"><button type="button" data-act="hl-fmt" data-v="bold" onmousedown="event.preventDefault()" aria-label="Bold"><i class="ri-bold"></i></button><button type="button" data-act="hl-fmt" data-v="italic" onmousedown="event.preventDefault()" aria-label="Italic"><i class="ri-italic"></i></button><button type="button" class="btn text sm ct-ph" data-act="hl-var" data-menu-anchor onmousedown="event.preventDefault()"><i class="ri-add-circle-line"></i>Insert variable</button><span class="grow"></span><span class="hl-legend"><i class="hl-v"></i>Filled automatically</span><span class="hl-legend"><i class="hl-s"></i>Filled at signing</span></div>` : '';
      const head = `<div class="row between g8 wrap"><div><h3 class="pt-h" style="margin:0"><i class="ri-mail-open-line"></i>${esc(lt.name)}</h3><span class="caption">${lt.stage === 'issued' ? 'Read-only. This is the exact letter the patient received.' : adm() ? 'Read-only for Admins. The assigned staff member prepares and sends this letter.' : lt.stage === 'draft' ? `Pulled from the template library (${lt.std ? 'Standard' : 'Staff created'}). Changes here apply to this letter only.` : isSigner(c) ? 'You are the designated signer, so you can edit this letter.' : `With ${esc(signer(lt.signer)[1])} for signature — read-only for you.`}</span></div>
        ${lt.stage === 'draft' && !adm() ? '<button class="btn outlined sm pt-dark" data-act="hl-reset"><i class="ri-refresh-line"></i>Reset to template</button>' : lt.stage === 'issued' ? '<button class="btn outlined sm pt-dark" data-act="hl-pdf"><i class="ri-download-2-line"></i>Download PDF</button>' : ''}</div>`;
      const valid = edit ? `<div class="hl-valid">${App.field('Valid for (days)', `<input type="number" min="1" max="3650" data-in="hl-valid" value="${lt.validDays}">`, { cls: 'sm' })}<span class="caption">Valid until is worked out on the day the letter is signed: issue date plus ${lt.validDays} days.</span></div>` : '';
